#include <stdio.h>



int main(void) {
    int a[20];
    for (int i = 0; i < 20; i++) scanf("%d", &a[i]);
    for (int i = 0; i < 19; i++) for (int j = 0; j < 19-i; j++)
        if (a[j] > a[j+1]) { int t = a[j]; a[j] = a[j+1]; a[j+1] = t; }
    for (int i = 0; i < 20; i++) printf("%d%c", a[i], i == 19 ? '\n' : ' ');
    return 0;
}
